"use client";

import { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import {
    Plus,
    Search,
    Shield,
    CheckCircle,
    XCircle,
    Eye,
    ChevronDown,
    LayoutGrid,
    List,
    Globe,
    Settings,
    ArrowUpRight,
    Percent,
} from "lucide-react";
import { cn } from "@/lib/utils";

interface InsurancePolicy {
    id: string;
    name: string;
    code: string;
    clauseType: string;
    description?: string;
    rate: number;
    isActive: boolean;
    cargoTypes?: any;
    transportModes?: any;
    incoterms?: any;
    geoScope: string;
    originPorts?: any;
    destinationPorts?: any;
    valuationBasis: string;
    minSumInsured?: number;
    maxSumInsured?: number;
    currency: string;
    minPremium?: number;
    hazardousLoading?: number;
    discount?: number;
    vat: number;
    additionalCovers?: any;
    startDate: string;
    endDate?: string;
    autoInvoice: boolean;
    autoIssue: boolean;
    manualApproval: boolean;
    internalNotes?: string;
}

type ViewMode = "grid" | "list";
type SortOption = "newest" | "oldest" | "highest" | "lowest";

export default function PoliciesListPage() {
    const { data: session, status } = useSession();
    const router = useRouter();
    const [policies, setPolicies] = useState<InsurancePolicy[]>([]);
    const [loading, setLoading] = useState(true);
    const [viewMode, setViewMode] = useState<ViewMode>("list");
    const [activeStatus, setActiveStatus] = useState("all");
    const [searchQuery, setSearchQuery] = useState("");
    const [sortBy, setSortBy] = useState<SortOption>("newest");

    useEffect(() => {
        if (status === "unauthenticated") {
            router.push("/login");
        } else if (session?.user?.role !== "ADMIN") {
            router.push("/dashboard");
        }
    }, [status, session, router]);

    useEffect(() => {
        if (session?.user?.role === "ADMIN") {
            fetchPolicies();
        }
    }, [session]);

    const fetchPolicies = async () => {
        try {
            const res = await fetch("/api/policies");
            if (res.ok) {
                const data = await res.json();
                setPolicies(data);
            } else {
                console.error("Failed to fetch policies");
            }
        } catch (error) {
            console.error("Error fetching policies:", error);
        } finally {
            setLoading(false);
        }
    };

    const statusFilters = [
        { id: "all", label: "All", count: policies.length },
        { id: "active", label: "Active", count: policies.filter(p => p.isActive).length },
        { id: "inactive", label: "Inactive", count: policies.filter(p => !p.isActive).length },
    ];

    const sortPolicies = (policiesToSort: InsurancePolicy[]) => {
        const sorted = [...policiesToSort];
        switch (sortBy) {
            case "newest":
                return sorted.sort((a, b) => new Date(b.startDate).getTime() - new Date(a.startDate).getTime());
            case "oldest":
                return sorted.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
            case "highest":
                return sorted.sort((a, b) => b.rate - a.rate);
            case "lowest":
                return sorted.sort((a, b) => a.rate - b.rate);
            default:
                return sorted;
        }
    };

    const filteredPolicies = sortPolicies(
        policies.filter((policy) => {
            const matchesStatus = 
                activeStatus === "all" || 
                (activeStatus === "active" && policy.isActive) ||
                (activeStatus === "inactive" && !policy.isActive);
            const matchesSearch = 
                policy.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                policy.code.toLowerCase().includes(searchQuery.toLowerCase()) ||
                policy.clauseType.toLowerCase().includes(searchQuery.toLowerCase());
            return matchesStatus && matchesSearch;
        })
    );

    const stats = {
        total: policies.length,
        active: policies.filter(p => p.isActive).length,
        inactive: policies.filter(p => !p.isActive).length,
        avgRate: policies.length > 0 ? (policies.reduce((sum, p) => sum + p.rate, 0) / policies.length).toFixed(2) : "0",
    };

    if (status === "loading" || loading) {
        return (
            <div className="flex items-center justify-center min-h-screen bg-gray-50">
                <div className="text-center">
                    <div className="relative w-12 h-12 mx-auto mb-4">
                        <div className="absolute inset-0 border-3 border-gray-200 rounded-full"></div>
                        <div className="absolute inset-0 border-3 border-brand-green border-t-transparent rounded-full animate-spin"></div>
                    </div>
                    <p className="text-sm text-gray-600 font-medium">Loading policies...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
                {/* Header */}
                <div className="mb-8">
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
                        <div>
                            <h1 className="text-2xl sm:text-3xl font-bold text-gray-900 mb-1">
                                Insurance Policies
                            </h1>
                            <p className="text-sm text-gray-600">
                                Manage underwriting policies and coverage rules
                            </p>
                        </div>
                        <Link 
                            href="/admin/policies/create"
                            className="inline-flex items-center justify-center gap-2 px-5 py-2.5 bg-brand-green text-white text-sm font-semibold rounded-lg hover:bg-brand-green/90 transition-colors shadow-sm"
                        >
                            <Plus className="w-4 h-4" />
                            Create Policy
                        </Link>
                    </div>

                    {/* Stats Cards */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 mb-6">
                        <div className="bg-white rounded-lg p-4 border border-gray-200">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-gray-100 rounded-lg flex items-center justify-center">
                                    <Shield className="w-5 h-5 text-gray-600" />
                                </div>
                                <div>
                                    <p className="text-xs text-gray-500 font-medium">Total</p>
                                    <p className="text-xl font-bold text-gray-900">{stats.total}</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white rounded-lg p-4 border border-emerald-200 bg-emerald-50/30">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-emerald-100 rounded-lg flex items-center justify-center">
                                    <CheckCircle className="w-5 h-5 text-emerald-600" />
                                </div>
                                <div>
                                    <p className="text-xs text-emerald-700 font-medium">Active</p>
                                    <p className="text-xl font-bold text-emerald-900">{stats.active}</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white rounded-lg p-4 border border-red-200 bg-red-50/30">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-red-100 rounded-lg flex items-center justify-center">
                                    <XCircle className="w-5 h-5 text-red-600" />
                                </div>
                                <div>
                                    <p className="text-xs text-red-700 font-medium">Inactive</p>
                                    <p className="text-xl font-bold text-red-900">{stats.inactive}</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white rounded-lg p-4 border border-gray-200">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
                                    <Percent className="w-5 h-5 text-blue-600" />
                                </div>
                                <div>
                                    <p className="text-xs text-gray-500 font-medium">Avg Rate</p>
                                    <p className="text-xl font-bold text-blue-900">{stats.avgRate}%</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Search and Controls Bar */}
                    <div className="bg-white rounded-lg border border-gray-200 p-4">
                        <div className="flex flex-col lg:flex-row gap-4">
                            {/* Search */}
                            <div className="flex-1 relative">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                                <input
                                    type="text"
                                    placeholder="Search by policy name, code, or clause type..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm text-gray-900 placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-brand-green/20 focus:border-brand-green transition-all"
                                />
                            </div>

                            {/* Sort Dropdown */}
                            <div className="relative">
                                <select
                                    value={sortBy}
                                    onChange={(e) => setSortBy(e.target.value as SortOption)}
                                    className="appearance-none w-full sm:w-auto pl-4 pr-10 py-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm font-medium text-gray-700 focus:outline-none focus:ring-2 focus:ring-brand-green/20 focus:border-brand-green transition-all cursor-pointer"
                                >
                                    <option value="newest">Newest First</option>
                                    <option value="oldest">Oldest First</option>
                                    <option value="highest">Highest Rate</option>
                                    <option value="lowest">Lowest Rate</option>
                                </select>
                                <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500 pointer-events-none" />
                            </div>

                            {/* View Mode Toggle */}
                            <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-lg">
                                <button
                                    onClick={() => setViewMode("grid")}
                                    className={`p-2 rounded transition-all ${
                                        viewMode === "grid"
                                            ? "bg-white text-brand-green shadow-sm"
                                            : "text-gray-500 hover:text-gray-700"
                                    }`}
                                    title="Grid view"
                                >
                                    <LayoutGrid className="w-4 h-4" />
                                </button>
                                <button
                                    onClick={() => setViewMode("list")}
                                    className={`p-2 rounded transition-all ${
                                        viewMode === "list"
                                            ? "bg-white text-brand-green shadow-sm"
                                            : "text-gray-500 hover:text-gray-700"
                                    }`}
                                    title="List view"
                                >
                                    <List className="w-4 h-4" />
                                </button>
                            </div>
                        </div>

                        {/* Status Filter Pills */}
                        <div className="flex flex-wrap gap-2 mt-4 pt-4 border-t border-gray-100">
                            {statusFilters.map((filter) => (
                                <button
                                    key={filter.id}
                                    onClick={() => setActiveStatus(filter.id)}
                                    className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-all ${
                                        activeStatus === filter.id
                                            ? "bg-brand-green text-white shadow-sm"
                                            : "bg-gray-100 text-gray-600 hover:bg-gray-200"
                                    }`}
                                >
                                    {filter.label}
                                    {filter.count > 0 && (
                                        <span className={`ml-1.5 ${
                                            activeStatus === filter.id ? "text-white/80" : "text-gray-500"
                                        }`}>
                                            ({filter.count})
                                        </span>
                                    )}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Policies Content */}
                {filteredPolicies.length === 0 ? (
                    <div className="bg-white rounded-lg border border-gray-200 p-12 text-center">
                        <div className="max-w-md mx-auto">
                            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Shield className="w-8 h-8 text-gray-400" />
                            </div>
                            <h3 className="text-lg font-semibold text-gray-900 mb-2">
                                No policies found
                            </h3>
                            <p className="text-sm text-gray-600">
                                Try adjusting your filters or search query
                            </p>
                        </div>
                    </div>
                ) : (
                    <>
                        {/* Grid View */}
                        {viewMode === "grid" && (
                            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                                {filteredPolicies.map((policy) => (
                                    <div
                                        key={policy.id}
                                        className="bg-white rounded-lg border border-gray-200 hover:border-gray-300 hover:shadow-md transition-all group"
                                    >
                                        {/* Card Header */}
                                        <div className="p-5 border-b border-gray-100">
                                            <div className="flex items-start justify-between gap-3 mb-3">
                                                <div className="flex items-start gap-3 flex-1 min-w-0">
                                                    <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center flex-shrink-0">
                                                        <Shield className="w-5 h-5 text-blue-600" />
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <h3 className="font-semibold text-gray-900 mb-1">
                                                            {policy.name}
                                                        </h3>
                                                        <p className="text-xs text-gray-500 font-mono">
                                                            {policy.code}
                                                        </p>
                                                    </div>
                                                </div>
                                                <div className={cn(
                                                    "flex items-center gap-1.5 px-2.5 py-1 rounded-md border",
                                                    policy.isActive 
                                                        ? "bg-emerald-50 border-emerald-200" 
                                                        : "bg-red-50 border-red-200"
                                                )}>
                                                    <div className={cn(
                                                        "w-1.5 h-1.5 rounded-full",
                                                        policy.isActive ? "bg-emerald-500" : "bg-red-500"
                                                    )} />
                                                    <span className={cn(
                                                        "text-xs font-semibold",
                                                        policy.isActive ? "text-emerald-700" : "text-red-700"
                                                    )}>
                                                        {policy.isActive ? "Active" : "Inactive"}
                                                    </span>
                                                </div>
                                            </div>

                                            <div className="flex items-center gap-2">
                                                <span className="inline-flex items-center gap-1 px-2 py-1 bg-gray-100 text-gray-700 rounded text-xs font-medium border border-gray-200">
                                                    {policy.clauseType}
                                                </span>
                                            </div>
                                        </div>

                                        {/* Card Body */}
                                        <div className="p-5">
                                            {/* Coverage Scope */}
                                            <div className="mb-4">
                                                <p className="text-xs text-gray-500 font-medium mb-2">Coverage Scope</p>
                                                <div className="flex items-center gap-2 text-sm text-gray-900 mb-2">
                                                    <Globe className="w-4 h-4 text-gray-500" />
                                                    <span>{policy.geoScope}</span>
                                                </div>
                                                <div className="flex flex-wrap gap-1">
                                                    {Array.isArray(policy.transportModes) && policy.transportModes.slice(0, 3).map((mode: string) => (
                                                        <span key={mode} className="text-xs px-2 py-0.5 bg-blue-50 text-blue-700 rounded border border-blue-200">
                                                            {mode}
                                                        </span>
                                                    ))}
                                                    {Array.isArray(policy.transportModes) && policy.transportModes.length > 3 && (
                                                        <span className="text-xs px-2 py-0.5 bg-gray-100 text-gray-600 rounded">
                                                            +{policy.transportModes.length - 3}
                                                        </span>
                                                    )}
                                                </div>
                                            </div>

                                            {/* Premium Rate */}
                                            <div className="bg-gray-50 rounded-lg p-4 mb-4">
                                                <p className="text-xs text-gray-500 font-medium mb-1">Premium Rate</p>
                                                <p className="text-2xl font-bold text-blue-600">
                                                    {policy.rate}%
                                                </p>
                                                {policy.minPremium && (
                                                    <p className="text-xs text-gray-500 mt-1">
                                                        Min: {policy.currency} {policy.minPremium.toLocaleString()}
                                                    </p>
                                                )}
                                            </div>

                                            {/* Dates */}
                                            <div className="grid grid-cols-2 gap-4 mb-4">
                                                <div>
                                                    <p className="text-xs text-gray-500 font-medium mb-1">Start Date</p>
                                                    <p className="text-xs text-gray-900">
                                                        {new Date(policy.startDate).toLocaleDateString('en-US', {
                                                            month: 'short',
                                                            day: 'numeric',
                                                            year: 'numeric'
                                                        })}
                                                    </p>
                                                </div>
                                                {policy.endDate && (
                                                    <div>
                                                        <p className="text-xs text-gray-500 font-medium mb-1">End Date</p>
                                                        <p className="text-xs text-gray-900">
                                                            {new Date(policy.endDate).toLocaleDateString('en-US', {
                                                                month: 'short',
                                                                day: 'numeric',
                                                                year: 'numeric'
                                                            })}
                                                        </p>
                                                    </div>
                                                )}
                                            </div>

                                            {/* Actions */}
                                            <div className="flex gap-2">
                                                <Link
                                                    href={`/admin/policies/${policy.id}`}
                                                    className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2 bg-gray-100 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-200 transition-colors"
                                                >
                                                    <Eye className="w-4 h-4" />
                                                    View Details
                                                </Link>
                                                <button className="inline-flex items-center justify-center gap-2 px-4 py-2 bg-gray-100 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-200 transition-colors">
                                                    <Settings className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        {/* List/Table View */}
                        {viewMode === "list" && (
                            <div className="bg-white rounded-lg border border-gray-200 overflow-hidden">
                                <div className="overflow-x-auto">
                                    <table className="w-full">
                                        <thead className="bg-gray-50 border-b border-gray-200">
                                            <tr>
                                                <th className="px-6 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wide">
                                                    Policy
                                                </th>
                                                <th className="px-6 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wide">
                                                    Clause Type
                                                </th>
                                                <th className="px-6 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wide">
                                                    Scope
                                                </th>
                                                <th className="px-6 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wide">
                                                    Premium Rate
                                                </th>
                                                <th className="px-6 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wide">
                                                    Status
                                                </th>
                                                <th className="px-6 py-3 text-right text-xs font-semibold text-gray-700 uppercase tracking-wide">
                                                    Actions
                                                </th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-100">
                                            {filteredPolicies.map((policy) => (
                                                <tr key={policy.id} className="hover:bg-gray-50 transition-colors">
                                                    <td className="px-6 py-4">
                                                        <div className="font-semibold text-gray-900">{policy.name}</div>
                                                        <div className="text-xs text-gray-500 mt-1 font-mono">
                                                            {policy.code}
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="font-medium text-gray-900">{policy.clauseType}</div>
                                                        <div className="text-xs text-gray-500 mt-1">
                                                            VAT: {policy.vat}%
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className="flex items-center gap-1.5 text-sm text-gray-700 mb-1">
                                                            <Globe className="w-3.5 h-3.5 text-gray-500" />
                                                            {policy.geoScope}
                                                        </div>
                                                        <div className="flex gap-1">
                                                            {Array.isArray(policy.transportModes) && policy.transportModes.slice(0, 3).map((m: string) => (
                                                                <span key={m} className="text-xs px-2 py-0.5 bg-blue-50 text-blue-700 rounded border border-blue-200">{m}</span>
                                                            ))}
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <span className="font-semibold text-blue-600 text-sm">{policy.rate}%</span>
                                                        {policy.minPremium && <div className="text-xs text-gray-500 mt-1">Min: ${policy.minPremium}</div>}
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <div className={cn(
                                                            "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md border text-xs font-semibold",
                                                            policy.isActive 
                                                                ? "bg-emerald-50 text-emerald-700 border-emerald-200" 
                                                                : "bg-red-50 text-red-700 border-red-200"
                                                        )}>
                                                            <div className={cn(
                                                                "w-1.5 h-1.5 rounded-full",
                                                                policy.isActive ? "bg-emerald-500" : "bg-red-500"
                                                            )} />
                                                            {policy.isActive ? "Active" : "Inactive"}
                                                        </div>
                                                    </td>
                                                    <td className="px-6 py-4 text-right">
                                                        <div className="flex items-center justify-end gap-2">
                                                            <Link
                                                                href={`/admin/policies/${policy.id}`}
                                                                className="inline-flex items-center gap-1 px-3 py-1.5 text-brand-green hover:bg-brand-green/10 rounded-lg text-sm font-medium transition-colors"
                                                            >
                                                                View
                                                                <ArrowUpRight className="w-3 h-3" />
                                                            </Link>
                                                            <button className="p-2 text-gray-400 hover:text-brand-green hover:bg-brand-green/10 rounded-lg transition-colors">
                                                                <Settings className="w-4 h-4" />
                                                            </button>
                                                        </div>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>

                                {/* Footer */}
                                <div className="px-6 py-4 border-t border-gray-200 bg-gray-50">
                                    <p className="text-sm text-gray-600 text-right">
                                        Showing <span className="font-semibold text-gray-900">{filteredPolicies.length}</span> of{" "}
                                        <span className="font-semibold text-gray-900">{policies.length}</span> policies
                                    </p>
                                </div>
                            </div>
                        )}

                        {/* Results Footer */}
                        {searchQuery && (
                            <div className="flex justify-end mt-4">
                                <button
                                    onClick={() => setSearchQuery("")}
                                    className="text-sm text-brand-green font-medium hover:underline"
                                >
                                    Clear search
                                </button>
                            </div>
                        )}
                    </>
                )}
            </div>
        </div>
    );
}